const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normal=s=>String(s||'').normalize('NFKC').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/[\s\u2066-\u2069\u200e\u200f]/g,'');
const stamp=v=>v&&v.toDate?new Intl.DateTimeFormat('ar-SA',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Riyadh'}).format(v.toDate()):'—';
const hex=b=>Array.from(new Uint8Array(b),v=>v.toString(16).padStart(2,'0')).join('');
const hash=async bytes=>hex(await crypto.subtle.digest('SHA-256',bytes));
const encode=bytes=>{let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s)};
const decode=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const displayName=s=>String(s||'').trim().replace(/\s+/g,' ').replace(/عبد(?=(?:الرحمن|الحكيم|التواب|المجيد|العزيز|الله))/g,'عبد ');
function recipients(teachers,state,admins=[]){
 const out=[...new Set(teachers)].map(name=>({key:'t:'+name,name:displayName(name),title:'معلم'}));
 const slots=[{role:-1,name:admins.find(p=>p.title==='مدير المدرسة')?.name||'مدير المدرسة'},...[0,1,2,3].map(role=>({role,name:state.names?.[role]})),...[4,5,6,7].map(role=>({role,name:state.mnames?.[role-4]}))];
 const enrolled=new Set(),matched=new Set();for(const person of admins){const entry=Object.values(state.employeeDirectory||{}).find(v=>v.active===true&&v.uid&&v.name===person.name);if(entry){enrolled.add(person.name);matched.add(person.name);out.push({key:'e:'+person.name,name:person.name,title:person.title})}}for(const slot of slots){if(!slot.name||/^(?:المسؤول|المشرف)\s*\d/.test(slot.name))continue;const n=normal(slot.name);const hits=admins.filter(p=>normal(p.name)===n||n.length>5&&normal(p.name).includes(n));const p=hits.length===1?hits[0]:null;if(p&&enrolled.has(p.name))continue;if(p)matched.add(p.name);out.push({key:'s:'+slot.role,name:p?.name||slot.name,title:p?.title||(slot.role<0?'مدير المدرسة':slot.role<4?'مسؤول متابعة':'مشرف')})}
 for(const p of admins)if(!matched.has(p.name))out.push({key:'',name:p.name,title:p.title,unlinked:true});return out;
}
