document.querySelectorAll('[data-sigfilter]').forEach(b=>b.onclick=()=>{filter=b.dataset.sigfilter;paint()});$('sigClearPerson').onclick=()=>{personName='';paint()};$('sigSearch').oninput=()=>{search=$('sigSearch').value.trim();paint()};
