 $('sigList').innerHTML=rows.map(d=>`<article class="sig-card"><h3>${esc(d.title)}</h3><small>${esc(d.fileName)} · ${esc(stamp(d.createdAt))}</small><p>${esc(STATEMENTS[d.kind])}</p><p>${d.signedCount} من ${d.targetKeys.length} أقرّوا · ${d.status==='archived'?'مغلق ومؤرشف':'قيد التوقيع'}</p><button data-sigdetail="${esc(d.id)}">${current?.admin?'التفاصيل والمتابعة':'فتح الملف والإقرار'}</button></article>`).join('')||'<p class="sig-note">لا توجد ملفات مطابقة.</p>';
