async function start(user,role){reset();if(!user)return;try{let key,admin=false;if(teacherPage){const snap=await fs().doc((root.EmployeePortal?'employeeProfiles/':'teacherProfiles/')+user.uid).get();if(!snap.exists||snap.data().active!==true)return;key=root.EmployeePortal?'e:'+snap.data().name:'t:'+snap.data().scheduleName}else{if(role==null)return;if(role===8){if(standalone)main.hidden=false;toast('طلبات التوقيع غير متاحة لحساب عرض التقارير. ادخل بحساب المنسوب الموجّه إليه الطلب.');return;}key='s:'+role;admin=role===-1}if(authObj().currentUser?.uid!==user.uid)return;current={uid:user.uid,actorUid:user.actorUid||user.uid,managerAccess:!!user.managerAccess,key,admin};if(nav)nav.hidden=false;$('sigNew').hidden=!admin;$('sigCircularNew').hidden=!admin;if(teacherPage||standalone)main.hidden=false;if(admin)refreshPeople();const col=fs().collection('signDocuments');const query=admin?col:col.where('targetKeys','array-contains',key);stop=query.onSnapshot(s=>{list=s.docs.map(x=>({id:x.id,...x.data()})).filter(d=>d.status!=='uploading').sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0));paint();if(selectedId)showDetail(selectedId)},err=>toast(message(err)))}catch(err){toast(message(err))}}
